import { chromium } from 'playwright';

/**
 * Script Lab, in a real browser.
 *
 * The done-when for this phase is a script generated by Voyager that is saved,
 * versioned, exported and compared. Every one of those is a thing that only
 * exists when it runs: the export is a browser download, the version history is
 * component state, and the diff is rendered from a comparison the modules can
 * compute but never display.
 */

const BASE = process.env.BASE_URL ?? 'http://localhost:3000';

let passed = 0;
let failed = 0;

function check(name, ok, detail) {
  if (ok) {
    passed += 1;
    console.log(`  ok   ${name}`);
  } else {
    failed += 1;
    console.log(`  FAIL ${name}${detail ? `  — ${detail}` : ''}`);
  }
}

function group(title) {
  console.log(`\n${title}`);
}

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });

try {
  group('Generating from the chart');

  await page.goto(`${BASE}/en/supercharts`, { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('canvas', { timeout: 20_000 });

  // Put a study on the chart first, so the script has something real to describe.
  await page.getByRole('button', { name: /Exponential moving averages/ }).click();
  await page.waitForTimeout(400);

  await page.getByRole('button', { name: 'Dock' }).click();
  await page.waitForTimeout(400);

  check('the dock opens on Script Lab', (await page.locator('text=Script Lab').count()) > 0);
  check(
    'and it says nothing is executed before anything is generated',
    (await page.locator('text=/Nothing here is executed/').count()) > 0
  );

  await page.getByRole('button', { name: 'Generate from the chart' }).click();
  await page.waitForTimeout(500);

  const source = page.getByRole('textbox', { name: 'Pine script source' });
  const text = await source.inputValue();

  check('a script is generated', text.length > 0);
  check('it is Pine v6', text.startsWith('//@version=6'), text.slice(0, 24));
  check(
    'it describes the study that is on the chart',
    /ta\.ema/.test(text) && !/ta\.sma\(close/.test(text),
    'the generated script does not match the study'
  );
  check('with exactly one declaration', (text.match(/^indicator\s*\(/gm) ?? []).length === 1);

  group('Diagnostics say what they are');

  const diagnostics = await page.locator('[class*="diagnostic"]').count();
  const cleanNote = await page.locator('text=/not the same as verified/').count();
  check(
    'a clean script is not called valid',
    diagnostics === 0 ? cleanNote > 0 : true,
    'a clean result claimed more than was checked'
  );

  // Break the script and watch the checker name the line.
  await source.fill('//@version=6\nindicator("Broken")\nspx = request.security("SPX", "D", close)\nplot(spx))');
  await page.waitForTimeout(500);

  const messages = await page.locator('[class*="diagnostic"]').allInnerTexts();
  const joined = messages.join(' | ');

  check('an unsupported call is named', /request\.security/.test(joined), joined.slice(0, 160));
  check('with the line it is on', /Line 3/.test(joined), joined.slice(0, 160));
  check('and a bracket error is caught', /bracket/i.test(joined), joined.slice(0, 160));
  check(
    'the status reflects the worst of them',
    (await page.locator('[class*="labStatus"]').first().textContent())?.includes('Error'),
    await page.locator('[class*="labStatus"]').first().textContent()
  );

  group('Fix with Voyager shows the diff first');

  await page.getByRole('button', { name: 'Fix with Voyager' }).first().click();
  await page.waitForTimeout(400);

  const fixCard = page.locator('[class*="fixCard"]');
  check('a fix card appears', (await fixCard.count()) > 0);

  const fixText = await fixCard.first().innerText();
  check('showing the change as a diff', /^[+−]/m.test(fixText), fixText.slice(0, 140));
  check(
    'and saying what it costs, not only what it helps',
    /second thing to fix|missing a value|Check that it was the right one/.test(fixText),
    fixText.slice(0, 200)
  );

  const beforeFix = await source.inputValue();
  await page.getByRole('button', { name: 'Cancel' }).click();
  await page.waitForTimeout(300);
  check(
    'cancelling changes nothing',
    (await source.inputValue()) === beforeFix,
    'the source changed after cancelling'
  );

  await page.getByRole('button', { name: 'Fix with Voyager' }).first().click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Apply this change' }).click();
  await page.waitForTimeout(500);

  const afterFix = await source.inputValue();
  check('applying changes exactly one line', afterFix !== beforeFix);
  check(
    'and the change is the one that was shown',
    afterFix.split(String.fromCharCode(10)).length ===
      beforeFix.split(String.fromCharCode(10)).length,
    'the line count changed'
  );

  group('Versions and the diff');

  await page.getByRole('button', { name: 'Keep version' }).click();
  await page.waitForTimeout(400);

  const versions = page.locator('[class*="versionRow"]');
  check('a second version is recorded', (await versions.count()) >= 2, `${await versions.count()}`);

  // Compare against the generated version, which is the oldest in the list.
  await versions.last().click();
  await page.waitForTimeout(400);

  const diffBlock = page.locator('[class*="diffBlock"]');
  check('the comparison renders', (await diffBlock.count()) > 0);

  const diffText = await diffBlock.first().innerText();
  check('it shows what was removed', /ta\.ema/.test(diffText), diffText.slice(0, 120));
  check('and what was added', /request\.security/.test(diffText), diffText.slice(0, 120));

  const counts = await page.locator('text=/\\+\\d+ −\\d+/').first().textContent();
  check('with a count of both', /\+\d+ −\d+/.test(counts ?? ''), counts ?? '');

  group('Export writes a Pine file');

  const download = page.waitForEvent('download', { timeout: 10_000 });
  await page.getByRole('button', { name: 'Export .pine' }).click();
  const file = await download;

  check('the download starts', Boolean(file));
  check('named as a Pine script', file.suggestedFilename().endsWith('.pine'), file.suggestedFilename());

  group('It survives a reload');

  await page.reload({ waitUntil: 'domcontentloaded' });
  await page.waitForSelector('canvas', { timeout: 20_000 });
  await page.getByRole('button', { name: 'Dock' }).click();
  await page.waitForTimeout(700);

  const restored = await page.getByRole('textbox', { name: 'Pine script source' }).inputValue();
  check('the script is still there', restored.includes('request.security'), restored.slice(0, 80));

  const restoredVersions = await page.locator('[class*="versionRow"]').count();
  check('and so is its history', restoredVersions >= 2, `${restoredVersions} versions`);
} catch (error) {
  failed += 1;
  console.log(`\n  FAIL the run stopped early — ${error.message}`);
} finally {
  await browser.close();
  console.log(`\n${passed}/${passed + failed} passed`);
  process.exit(failed ? 1 : 0);
}
